create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls; create role authenticator nologin; create role supabase_admin superuser; create role supabase_auth_admin; create role supabase_storage_admin; create role dashboard_user;
create schema auth; create schema storage; create schema extensions; create schema vault; create schema cron; create schema net; create schema graphql; create schema realtime; create schema supabase_functions;
create extension if not exists pgcrypto schema extensions; create extension if not exists "uuid-ossp" schema extensions;
create table auth.users(id uuid primary key default gen_random_uuid(), email text, raw_user_meta_data jsonb default '{}', raw_app_meta_data jsonb default '{}', created_at timestamptz default now(), updated_at timestamptz, last_sign_in_at timestamptz, email_confirmed_at timestamptz, phone text, banned_until timestamptz, deleted_at timestamptz, is_anonymous bool default false, encrypted_password text, confirmed_at timestamptz, is_sso_user bool default false);
create table auth.identities(id uuid primary key default gen_random_uuid(), user_id uuid, provider text, identity_data jsonb);
create table auth.sessions(id uuid primary key, user_id uuid);
create or replace function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create or replace function auth.role() returns text language sql stable as $$ select current_setting('request.jwt.claim.role',true) $$;
create or replace function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb $$;
create table storage.buckets(id text primary key, name text, public bool, file_size_limit bigint, allowed_mime_types text[], owner uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table storage.objects(id uuid primary key default gen_random_uuid(), bucket_id text, name text, owner uuid, metadata jsonb, created_at timestamptz default now(), updated_at timestamptz default now(), path_tokens text[] generated always as (string_to_array(name,'/')) stored);
alter table storage.objects enable row level security;
create or replace function storage.foldername(name text) returns text[] language sql immutable as $$ select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1] $$;
create or replace function storage.filename(name text) returns text language sql immutable as $$ select (string_to_array(name,'/'))[array_length(string_to_array(name,'/'),1)] $$;
create table vault.secrets(id uuid primary key default gen_random_uuid(), name text unique, secret text, description text);
create view vault.decrypted_secrets as select *, secret as decrypted_secret from vault.secrets;
create or replace function vault.create_secret(s text, n text default null, d text default null) returns uuid language sql as $$ insert into vault.secrets(name,secret,description) values(n,s,d) returning id $$;
create table cron.job(jobid bigserial primary key, jobname text unique, schedule text, command text, active bool default true);
create or replace function cron.schedule(n text, s text, c text) returns bigint language sql as $$ insert into cron.job(jobname,schedule,command) values(n,s,c) on conflict(jobname) do update set schedule=excluded.schedule,command=excluded.command returning jobid $$;
create or replace function cron.unschedule(n text) returns bool language sql as $$ delete from cron.job where jobname=n returning true $$;
create or replace function net.http_post(url text, body jsonb default '{}', params jsonb default '{}', headers jsonb default '{}', timeout_milliseconds int default 5000) returns bigint language sql as $$ select 0::bigint $$;
create publication supabase_realtime;
